begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,other_property uuid,actor_id uuid,request_id uuid);
insert into fixture values(gen_random_uuid(),gen_random_uuid(),'11111111-1111-1111-1111-111111111111',gen_random_uuid());
insert into public.properties(id,org_id,name)select property_id,'22222222-2222-2222-2222-222222222222'::uuid,'MarketVision intake rollback fixture'from fixture union all select other_property,'22222222-2222-2222-2222-222222222222'::uuid,'MarketVision other intake rollback fixture'from fixture;
create function pg_temp.fail_intake_event()returns trigger language plpgsql as $$begin if new.action='market.intake.applied'and current_setting('p11.fixture.fail_intake',true)='yes'then raise exception 'Injected intake history failure';end if;return new;end$$;
create trigger fixture_intake_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_intake_event();
do $$declare f fixture;entry public.marketvision_intakes;r jsonb;input jsonb;preview jsonb;decision jsonb;decision_id uuid:=gen_random_uuid();other_id uuid:=gen_random_uuid();candidate_id uuid;ctx uuid;begin
 select *into f from fixture;
 input:='{"rawText":"  North sample (Test City): from $2000.\n\nSouth sample: promotion reported.  ","reason":"Review original operator notes"}';
 preview:='[{"name":"North sample","location":"Test City","url":"https://example.com/","sourceText":"North sample (Test City): from $2000.","claims":{"priceText":"from $2000"}},{"name":"South sample","location":null,"url":null,"sourceText":"South sample: promotion reported.","claims":{"promotionText":"promotion reported"}}]';
 perform pg_temp.check(not has_table_privilege('authenticated','public.marketvision_intakes','select')and not has_table_privilege('authenticated','public.marketvision_intakes','insert')and not has_function_privilege('authenticated','public.begin_marketvision_intake(uuid,uuid,uuid,jsonb,jsonb)','execute'),'private records and RPCs are unavailable to direct browser access');
 perform pg_temp.check(public.begin_marketvision_intake(f.request_id,f.property_id,gen_random_uuid(),input,preview)->>'state'='forbidden','preparation requires current actor access');
 r:=public.begin_marketvision_intake(f.request_id,f.property_id,f.actor_id,input,preview);perform pg_temp.check(r->>'state'='preview_ready','preparation saves complete preview');
 select *into entry from public.marketvision_intakes where id=f.request_id;candidate_id:=(entry.preview->0->>'id')::uuid;ctx:=entry.context_id;
 perform pg_temp.check(entry.input=input and entry.recipe='operator-notes-v1'and jsonb_array_length(entry.preview)=2 and entry.preview->0->>'sourceText'=preview->0->>'sourceText','exact raw notes and paragraph evidence retained with parser recipe');
 perform pg_temp.check(not exists(select 1 from public.competitors where property_id=f.property_id),'preview creates no competitor');
 perform pg_temp.check((select actor_id=f.actor_id and shared_job_ref=f.request_id and context_snapshot_ref=ctx from public.shared_action_events where id=f.request_id),'preparation records actor and job/context links');
 perform pg_temp.check(public.begin_marketvision_intake(f.request_id,f.property_id,f.actor_id,input,preview)->>'requestId'=f.request_id::text and(select count(*)=1 from public.marketvision_intakes where property_id=f.property_id),'lost preparation response returns original identity');
 perform pg_temp.check(public.begin_marketvision_intake(f.request_id,f.property_id,f.actor_id,input||'{"rawText":"Changed long enough notes"}',preview)->>'state'='request_conflict','same request cannot replace original notes');
 perform pg_temp.check(public.read_marketvision_intakes(f.other_property,f.actor_id,f.request_id)->>'state'='not_found','private details cannot cross properties');
 perform pg_temp.check(public.read_marketvision_intakes(f.property_id,gen_random_uuid(),f.request_id)->>'state'='forbidden','read checks current membership');
 begin update public.marketvision_intakes set preview='[]'where id=f.request_id;raise exception 'MISSING immutable preview';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Saved notes and preview cannot change','retained preview cannot be edited');end;
 begin update public.shared_jobs set lifecycle_status='cancelled'where id=f.request_id;raise exception 'MISSING generic job fence';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Review this saved intake in MarketVision','generic cancellation cannot bypass intake review');end;
 begin update public.shared_context_snapshots set context_payload='{}'where id=ctx;raise exception 'MISSING context fence';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Saved intake context is immutable','original context cannot be rewritten');end;
 decision:=jsonb_build_object('intakeId',entry.id,'expectedVersion',1,'previewHash',entry.preview_hash,'action','apply','reason','Reviewed corrected identities','acknowledgeUnverified',true,'candidates',jsonb_build_array(jsonb_build_object('id',candidate_id,'action','add','propertyType','townhome','name','Corrected North','location','Reviewed City','url','https://example.com/reviewed'),jsonb_build_object('id',entry.preview->1->>'id','action','skip')));
 perform pg_temp.check(public.decide_marketvision_intake(decision_id,f.other_property,f.actor_id,decision)->>'state'='not_found','approval cannot cross properties');
 perform pg_temp.check(public.decide_marketvision_intake(decision_id,f.property_id,f.actor_id,decision||'{"expectedVersion":9}')->>'state'='stale_intake','stale review rejected');
 perform pg_temp.check(public.decide_marketvision_intake(decision_id,f.property_id,f.actor_id,decision||'{"previewHash":"different"}')->>'state'='stale_intake','exact original preview required');
 begin perform public.decide_marketvision_intake(decision_id,f.property_id,f.actor_id,decision||'{"acknowledgeUnverified":false}');raise exception 'MISSING source acknowledgment';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm like 'Review every candidate%','source claims require explicit acknowledgment');end;
 begin perform public.decide_marketvision_intake(decision_id,f.property_id,f.actor_id,jsonb_set(decision,'{candidates}',jsonb_build_array(decision->'candidates'->0)));raise exception 'MISSING full selection';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm like 'Review every candidate%','partial candidate selection rejected');end;
 begin perform public.decide_marketvision_intake(decision_id,f.property_id,f.actor_id,jsonb_set(decision,'{candidates}',jsonb_build_array(decision->'candidates'->0,decision->'candidates'->0)));raise exception 'MISSING repeated identity';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Review each saved candidate once','duplicate candidate identities rejected');end;
 begin perform public.decide_marketvision_intake(decision_id,f.property_id,f.actor_id,jsonb_set(decision,'{candidates,0,id}',to_jsonb(gen_random_uuid())));raise exception 'MISSING unknown candidate';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Candidate is not in this saved preview','forged candidate rejected');end;
 begin perform public.decide_marketvision_intake(decision_id,f.property_id,f.actor_id,jsonb_set(decision,'{candidates,0,url}','"javascript:alert(1)"'));raise exception 'MISSING unsafe address';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Use a complete HTTP or HTTPS source address','unsafe address rejected');end;
 insert into public.competitors(property_id,name,is_active)values(f.property_id,'corrected north',false);
 perform pg_temp.check(public.decide_marketvision_intake(decision_id,f.property_id,f.actor_id,decision)->>'state'='duplicate_competitor','archived same-name competitor cannot be overwritten or duplicated');
 delete from public.competitors where property_id=f.property_id;
 perform pg_temp.check(public.decide_marketvision_intake(decision_id,f.property_id,f.actor_id,jsonb_set(decision,'{candidates,1}',jsonb_build_object('id',entry.preview->1->>'id','action','add','propertyType','townhome','name','Corrected North','location',null,'url',null)))->>'state'='duplicate_selection','duplicate reviewed names rejected before writes');
 perform set_config('p11.fixture.fail_intake','yes',true);
 begin perform public.decide_marketvision_intake(decision_id,f.property_id,f.actor_id,decision);raise exception 'MISSING atomic failure';exception when others then if sqlerrm like 'MISSING%'then raise;end if;raise notice 'Atomic rollback error: %',sqlerrm;perform pg_temp.check(sqlerrm='Injected intake history failure','history failure surfaces');end;
 perform set_config('p11.fixture.fail_intake','no',true);
 perform pg_temp.check(not exists(select 1 from public.competitors where property_id=f.property_id)and not exists(select 1 from public.marketvision_decisions where id=candidate_id)and(select state='preview_ready'and version=1 from public.marketvision_intakes where id=f.request_id),'competitors and child decisions roll back with failed intake receipt');
 r:=public.decide_marketvision_intake(decision_id,f.property_id,f.actor_id,decision);perform pg_temp.check(r->>'state'='saved'and jsonb_array_length(r->'created')=1 and jsonb_array_length(r->'skipped')=1,'complete review applies exact add/skip selection');
 perform pg_temp.check((select name='Corrected North'and address='Reviewed City'and website_url='https://example.com/reviewed'and property_type='townhome'from public.competitors where id=candidate_id),'only reviewed identity corrections applied');
 perform pg_temp.check(not exists(select 1 from public.competitor_units where competitor_id=candidate_id)and not exists(select 1 from public.competitor_brand_intelligence where competitor_id=candidate_id),'reported prices and brand claims never become verified product facts');
 perform pg_temp.check((select d.input=decision and d.actor_id=f.actor_id from public.marketvision_decisions d where d.id=decision_id)and(select shared_job_ref=f.request_id and context_snapshot_ref=ctx from public.shared_action_events where id=decision_id),'exact corrections, reason and linked actor evidence retained');
 perform pg_temp.check(public.decide_marketvision_intake(decision_id,f.property_id,f.actor_id,decision)->>'state'='replayed'and(select count(*)=1 from public.competitors where property_id=f.property_id),'lost apply response cannot duplicate effects');
 perform pg_temp.check(public.decide_marketvision_intake(gen_random_uuid(),f.property_id,f.actor_id,decision)->>'state'='stale_intake','different decision identity cannot reapply original preview');
 perform pg_temp.check(public.begin_marketvision_intake(f.request_id,f.property_id,f.actor_id,input,preview)->>'state'='applied','original prepare identity recovers later final state');
 perform pg_temp.check(public.read_marketvision_monitoring(f.property_id,f.actor_id,'all',f.request_id)->'run'->>'request_state'='applied','monitoring reads private intake outcome');
 perform pg_temp.check(public.read_marketvision_intakes(f.property_id,f.actor_id,f.request_id)->'decision'->'input'=decision,'detail preserves reviewed corrections after reload');
 perform public.begin_marketvision_intake(other_id,f.property_id,f.actor_id,input,preview);select *into entry from public.marketvision_intakes where id=other_id;
 perform pg_temp.check(public.decide_marketvision_intake(gen_random_uuid(),f.property_id,f.actor_id,jsonb_build_object('intakeId',entry.id,'expectedVersion',1,'previewHash',entry.preview_hash,'action','stop','reason','Stop the entire original preview'))->>'state'='saved','explicit stop retained without competitor creation');
 perform pg_temp.check((select state='stopped'and jsonb_array_length(result->'created')=0 from public.marketvision_intakes where id=other_id),'stopped work has no created identities');
 begin delete from public.marketvision_intakes where id=other_id;raise exception 'MISSING retained history';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Saved intake is retained','completed/stopped records cannot be erased');end;
 perform pg_temp.check(public.read_marketvision_intakes(f.property_id,f.actor_id,null,f.request_id)->>'state'='ready'and public.read_marketvision_intakes(f.other_property,f.actor_id,null,f.request_id)->>'state'='cursor_changed','history cursors are property-scoped');
end$$;
-- History beyond the platform's default row cap and deterministic same-time keysets.
insert into public.shared_jobs(id,org_id,property_id,domain,subject_type,subject_id,lifecycle_status,payload)select md5('intake-history-'||n)::uuid,'22222222-2222-2222-2222-222222222222'::uuid,f.property_id,'marketvision.intake','competitor_intake',n::text,'queued','{}'::jsonb from fixture f cross join generate_series(1,1002)n;
insert into public.marketvision_intakes(id,org_id,property_id,actor_id,context_id,input,input_hash,preview,preview_hash,recipe,created_at)select j.id,j.org_id,j.property_id,f.actor_id,(select context_id from public.marketvision_intakes where id=f.request_id),'{}','fixture','[]','fixture','operator-notes-v1','2020-01-01'from fixture f join public.shared_jobs j on j.property_id=f.property_id where not exists(select 1 from public.marketvision_intakes i where i.id=j.id);
do $$declare f fixture;cursor_id uuid;page jsonb;ids uuid[]:='{}';begin select *into f from fixture;loop page:=public.read_marketvision_intakes(f.property_id,f.actor_id,null,cursor_id);select ids||array_agg((value->>'id')::uuid)into ids from jsonb_array_elements(page->'intakes');cursor_id:=(page->>'nextCursor')::uuid;exit when cursor_id is null;end loop;perform pg_temp.check(array_length(ids,1)=1004 and(select count(distinct id)=1004 from unnest(ids)id),'all 1004 saved intakes page exactly once including timestamp ties');perform pg_temp.check((page->>'total')::integer=1004,'complete history count exceeds default cap');end$$;
select count(*)as passed_intake_assertions from checks;
rollback;
